CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
CREATE TABLE roles(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', builtin INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE role_permissions(role_id INTEGER NOT NULL REFERENCES roles(id), permission TEXT NOT NULL, PRIMARY KEY(role_id,permission));
CREATE TABLE users(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, auth_version INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE user_roles(user_id INTEGER NOT NULL REFERENCES users(id), role_id INTEGER NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, auth_version INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE hosts(id INTEGER PRIMARY KEY, hostname TEXT NOT NULL, alias TEXT NOT NULL DEFAULT '', inventory TEXT NOT NULL DEFAULT '{}', snapshot TEXT NOT NULL DEFAULT '{}', last_seen INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE host_samples(id INTEGER PRIMARY KEY, host_id INTEGER NOT NULL REFERENCES hosts(id), at INTEGER NOT NULL, cpu REAL, memory REAL, net_in REAL, net_out REAL);
CREATE INDEX host_samples_time ON host_samples(host_id,at);
CREATE TABLE monitors(id INTEGER PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('HTTP','TCP','SSL','MySQL','Redis')), target TEXT NOT NULL, group_name TEXT NOT NULL, interval_seconds INTEGER NOT NULL CHECK(interval_seconds>=15), timeout_seconds INTEGER NOT NULL CHECK(timeout_seconds BETWEEN 1 AND 30), expected_status INTEGER NOT NULL DEFAULT 200, failure_threshold INTEGER NOT NULL DEFAULT 3, ssl_days INTEGER NOT NULL DEFAULT 14, username TEXT NOT NULL DEFAULT '', secret TEXT NOT NULL DEFAULT '', tls INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL DEFAULT 'unknown', latency REAL, detail TEXT NOT NULL DEFAULT '', checked_at INTEGER NOT NULL DEFAULT 0, next_check INTEGER NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, deleted_at INTEGER);
CREATE TABLE check_results(id INTEGER PRIMARY KEY, monitor_id INTEGER NOT NULL REFERENCES monitors(id), at INTEGER NOT NULL, state TEXT NOT NULL, latency REAL NOT NULL, detail TEXT NOT NULL);
CREATE INDEX check_results_time ON check_results(monitor_id,at);
CREATE TABLE jobs(id INTEGER PRIMARY KEY, monitor_id INTEGER NOT NULL REFERENCES monitors(id), state TEXT NOT NULL DEFAULT 'queued', created_at INTEGER NOT NULL, finished_at INTEGER, error TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX jobs_active ON jobs(monitor_id) WHERE state IN ('queued','running');
CREATE TABLE alerts(id INTEGER PRIMARY KEY, fingerprint TEXT NOT NULL, resource_kind TEXT NOT NULL, resource_id INTEGER NOT NULL, resource TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, severity TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open', opened_at INTEGER NOT NULL, recovered_at INTEGER, ack_by INTEGER REFERENCES users(id), ack_at INTEGER, silence_until INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX alerts_active ON alerts(fingerprint) WHERE state <> 'resolved';
CREATE TABLE alert_activity(id INTEGER PRIMARY KEY, alert_id INTEGER NOT NULL REFERENCES alerts(id), at INTEGER NOT NULL, actor TEXT NOT NULL, message TEXT NOT NULL);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY, at INTEGER NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, resource TEXT NOT NULL);
INSERT INTO schema_migrations(version) VALUES(1);
